

$(document).ready(function() {
    function updateSubjects() {
        let class_id = $("#class_id").val();
        let semester_id = $("#semester_id").val();

        if (class_id || semester_id) {
            subject_name(class_id, semester_id);
        }
    }

    $("#class_id").change(updateSubjects);
    $("#semester_id").change(updateSubjects);
});

function subject_name(class_id, semester_id) {
    let sendingData = {
        "action": "subject_name",
        "class_id": class_id,
        "semester_id": semester_id
    };

    $.ajax({
        method: "POST",
        dataType: "JSON",
        url: "../APi/studentview.php",
        data: sendingData,
        success: function(data) {
            let status = data.status;
            let response = data.data;
            let html = '';

            if (status) {
                $("#subject_id").html('<option value="">Select Subject</option>');
                response.forEach(res => {
                    html += `<option value="${res['subject_id']}">${res['subject_name']}</option>`;
                });
                $("#subject_id").append(html);
            } else {
                // alert("Error: " + data.message);
            }
        },
        error: function(xhr, status, error) {
            console.error("AJAX Error: ", status, error);
        }
    });
}



